// A category id: a positive int or a string of decimal digits within signed INT. 0 for everything else.
private function seoProCategoryId($value) {
    if (is_int($value)) {
        return ($value >= 1 && $value <= 2147483647) ? $value : 0;
    }

    if (!is_string($value) || !preg_match('/^[0-9]+$/D', $value)) {
        return 0;
    }

    $value = ltrim($value, '0');

    if ($value === '' || strlen($value) > 10 || (strlen($value) === 10 && strcmp($value, '2147483647') > 0)) {
        return 0;
    }

    return (int)$value;
}

// The categories of the product: valid ids, without duplicates, in the order they were sent.
// No key is an empty list; a key with anything but an array, null included, is a wrong call.
private function seoProCategories($data) {
    if (!is_array($data) || !array_key_exists('product_category', $data)) {
        return array();
    }

    if (!is_array($data['product_category'])) {
        throw new \InvalidArgumentException('SEO Pro: product_category must be an array');
    }

    $categories = array();

    foreach ($data['product_category'] as $value) {
        $category_id = $this->seoProCategoryId($value);

        if ($category_id && !in_array($category_id, $categories, true)) {
            $categories[] = $category_id;
        }
    }

    return $categories;
}

// Marks one of the saved categories of the product as the main one. Never creates a link.
private function seoProSetMainCategory($product_id, $data) {
    // The column main_category is not created yet
    if ($this->config->get('seo_pro_schema_failed')) {
        return;
    }

    $saved = array();

    foreach ($this->db->query("SELECT category_id FROM " . DB_PREFIX . "product_to_category WHERE product_id = '" . (int)$product_id . "'")->rows as $row) {
        $saved[] = (int)$row['category_id'];
    }

    $categories = array_values(array_intersect(isset($data['product_category']) && is_array($data['product_category']) ? $data['product_category'] : array(), $saved));

    if (!$categories) {
        return;
    }

    $main_category_id = $this->seoProCategoryId(isset($data['main_category_id']) ? $data['main_category_id'] : 0);

    // No choice, or the chosen category is not a category of the product: the first one
    if (!in_array($main_category_id, $categories, true)) {
        $main_category_id = $categories[0];
    }

    $this->db->query("UPDATE " . DB_PREFIX . "product_to_category SET main_category = IF(category_id = '" . (int)$main_category_id . "', 1, 0) WHERE product_id = '" . (int)$product_id . "'");
}

public function getProductMainCategoryId($product_id) {
    // The column main_category is not created yet
    if ($this->config->get('seo_pro_schema_failed')) {
        return 0;
    }

    $query = $this->db->query("SELECT category_id FROM " . DB_PREFIX . "product_to_category WHERE product_id = '" . (int)$product_id . "' AND main_category = '1' LIMIT 1");

    return ($query->num_rows ? (int)$query->row['category_id'] : 0);
}

