}

// SEO Pro: the descriptions of the manufacturer. While the table is not ready the manufacturer is not saved
if (!$this->config->get('seo_pro_manufacturer_description_ready')) {
	if (!isset($this->error['warning'])) {
		$this->error['warning'] = $this->language->get('error_seo_pro_md_schema');
	}
} elseif (is_array($this->request->post) && array_key_exists('manufacturer_description', $this->request->post)) {
	$seo_pro_errors = Seo_pro_schema::manufacturerErrors($this->request->post['manufacturer_description']);

	foreach ($seo_pro_errors['fields'] as $language_id => $fields) {
		foreach ($fields as $field => $error) {
			$this->error['seo_pro_description'][$language_id][$field] = $this->language->get($field == 'description' ? 'error_seo_pro_md_description' : 'error_seo_pro_md_text');
		}
	}

	if (!isset($this->error['warning']) && ($seo_pro_errors['container'] || $seo_pro_errors['fields'])) {
		$this->error['warning'] = $this->language->get($seo_pro_errors['container'] ? 'error_seo_pro_md_invalid' : 'error_seo_pro_md_warning');
	}
}

// SEO Pro: the descriptions are deleted with the manufacturer, so the table must be ready
if (!$this->config->get('seo_pro_manufacturer_description_ready')) {
	$this->error['warning'] = $this->language->get('error_seo_pro_md_schema');
}

// SEO Pro: the descriptions of the manufacturer. Each field: the form, the stored value, an empty text
$data['seo_pro_description_ready'] = (bool)$this->config->get('seo_pro_manufacturer_description_ready');

if (!$data['seo_pro_description_ready'] && !$data['error_warning']) {
	$data['error_warning'] = $this->language->get('error_seo_pro_md_schema');
}

$data['error_seo_pro_description'] = isset($this->error['seo_pro_description']) ? $this->error['seo_pro_description'] : array();

$data['manufacturer_description'] = Seo_pro_schema::manufacturerFormValues(
	isset($this->request->post['manufacturer_description']) ? $this->request->post['manufacturer_description'] : array(),
	isset($this->request->get['manufacturer_id']) ? $this->model_catalog_manufacturer->getManufacturerDescriptions($this->request->get['manufacturer_id']) : array()
);

$_['tab_seo_pro_description']        = 'Description';
$_['entry_seo_pro_description']      = 'Description';
$_['entry_seo_pro_meta_title']       = 'Meta Tag Title';
$_['entry_seo_pro_meta_h1']          = 'HTML Tag H1';
