// SEO Pro: the description in the current language; a manufacturer without it is found as before
if ($this->config->get('seo_pro_manufacturer_description_ready')) {
	$query = $this->db->query("SELECT m.*, m2s.store_id, md.description, md.meta_title, md.meta_h1, md.meta_description, md.meta_keyword FROM " . DB_PREFIX . "manufacturer m LEFT JOIN " . DB_PREFIX . "manufacturer_to_store m2s ON (m.manufacturer_id = m2s.manufacturer_id) LEFT JOIN " . DB_PREFIX . "manufacturer_description md ON (m.manufacturer_id = md.manufacturer_id AND md.language_id = '" . (int)$this->config->get('config_language_id') . "') WHERE m.manufacturer_id = '" . (int)$manufacturer_id . "' AND m2s.store_id = '" . (int)$this->config->get('config_store_id') . "'");

	return $query->row;
}

// SEO Pro: the meta tags of the manufacturer in the current language; an empty field keeps the core value
if ($this->config->get('seo_pro_manufacturer_description_ready')) {
	if (isset($manufacturer_info['meta_title']) && is_string($manufacturer_info['meta_title']) && $manufacturer_info['meta_title'] !== '') {
		$this->document->setTitle(Seo_pro_schema::text($manufacturer_info['meta_title']));
	}

	if (isset($manufacturer_info['meta_description']) && is_string($manufacturer_info['meta_description']) && $manufacturer_info['meta_description'] !== '') {
		$this->document->setDescription(Seo_pro_schema::text($manufacturer_info['meta_description']));
	}

	if (isset($manufacturer_info['meta_keyword']) && is_string($manufacturer_info['meta_keyword']) && $manufacturer_info['meta_keyword'] !== '') {
		$this->document->setKeywords(Seo_pro_schema::text($manufacturer_info['meta_keyword']));
	}
}

// SEO Pro: a filled H1 replaces the heading ('0' is a filled H1); the description for themes that show it
$data['description'] = '';

if ($this->config->get('seo_pro_manufacturer_description_ready')) {
	if (isset($manufacturer_info['meta_h1']) && is_string($manufacturer_info['meta_h1']) && $manufacturer_info['meta_h1'] !== '') {
		$data['heading_title'] = Seo_pro_schema::text($manufacturer_info['meta_h1']);
	}

	if (isset($manufacturer_info['description']) && is_string($manufacturer_info['description'])) {
		$data['description'] = html_entity_decode($manufacturer_info['description'], ENT_QUOTES, 'UTF-8');
	}
}
